{
  "selected_angles": [
    {
      "local_key": "m1-geography-and-buyer-knowledge",
      "rank": 1,
      "disposition": "SELECT",
      "title": "Let local client knowledge shape the map",
      "central_point": "Geographic targeting is more useful when it reflects the venue owner's experience with both where clients come from and how well inquiries from different areas fit, rather than reach alone.",
      "why_worthwhile": "The discussion shows a specific strategic judgment: Lauren described both clients and less-qualified inquiries from the valley cities, then identified stronger ideal-client regions. Whitney used that context to recommend opening targeting toward other areas while leaving those four cities out. That exchange makes client knowledge a visible input to WIA's advertising judgment.",
      "audience": "Wedding venues and other location-dependent wedding businesses weighing whether to expand geographic targeting when a region produces inquiries but uncertain fit.",
      "intended_shift": "Consider inquiry quality and the owner's market knowledge alongside geographic reach when deciding which areas to target.",
      "primary_pillar": "WARM",
      "content_type": "process",
      "strategic_rationale": "A process-led example can build trust in how WIA combines advertising review with a client's knowledge of their market. It does not claim the recommendation improved results.",
      "source_demonstration": "Lauren says the four valley cities send some clients, but she has seen price sensitivity and many inquiries she considered not very high quality; she contrasts those areas with regions she associates more with ideal clients. Whitney then recommends adding the Bay Area, LA, and San Diego while leaving off the four valley cities.",
      "moment_keys": [
        "m1-geography-and-buyer-knowledge"
      ],
      "evidence_refs": [
        "m1.t0285",
        "m1.t0291",
        "m1.t0296",
        "m1.t0299",
        "m1.t0302",
        "m1.t0312",
        "m1.t0313"
      ],
      "claims": [
        {
          "claim": "Lauren reports that the valley cities send some clients and that she has observed price sensitivity and inquiries she did not consider especially high quality from a previous campaign targeting that area.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0291",
            "m1.t0296",
            "m1.t0299"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Lauren identifies the Bay Area, San Francisco, San Jose, LA, and Santa Barbara as areas more typical of her ideal client.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0302"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Whitney recommends opening targeting to the Bay Area, LA, and San Diego and leaving the four valley cities off, connecting the recommendation to where the client says ideal couples come from.",
          "state": "proposed_action",
          "source_refs": [
            "m1.t0312",
            "m1.t0313",
            "m1.t0316"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Using the owner's market knowledge about client fit as an input to targeting is a useful way to frame this exchange for other location-dependent wedding businesses.",
          "state": "editorial_inference",
          "source_refs": [
            "m1.t0291",
            "m1.t0296",
            "m1.t0302",
            "m1.t0313"
          ],
          "knowledge_refs": [
            "H006",
            "H011"
          ]
        }
      ],
      "claim_boundaries": [
        "Keep Lauren's inquiry-quality and price-sensitivity observations attributed to her; they are not quantified comparisons or proof that geography caused inquiry quality.",
        "Keep Whitney's recommendation specific to this venue and market. Do not present these locations as a general targeting rule.",
        "The call supports the recommendation, not implementation or a resulting change in inquiry quality."
      ],
      "development_direction": "Show the sequence from the owner's mixed experience with the four cities, to her view of stronger ideal-client regions, to Whitney's specific recommendation. Keep the distinction between some clients coming from an area and that area being a strong fit.",
      "tension": "The valley cities bring some clients, but the owner's experience also raises questions about the fit of inquiries from a previous campaign there.",
      "offer_connection": null,
      "possible_format": "A short process breakdown centered on the targeting discussion.",
      "judgments": {
        "audience_relevance": {
          "value": 4,
          "reason": "Location-dependent wedding businesses can recognize the decision about including areas that produce inquiries of uncertain fit."
        },
        "strategic_value_brand_fit": {
          "value": 5,
          "reason": "The example makes WIA's combination of advertising judgment and client market knowledge tangible."
        },
        "distinctiveness": {
          "value": 4,
          "reason": "The concrete choice among actual regions gives the broader targeting point a specific decision sequence."
        },
        "appropriate_depth": {
          "value": 4,
          "reason": "The owner's observations and Whitney's recommendation provide enough reasoning, provided the piece stays bounded to this venue."
        },
        "voice_framing": {
          "value": 4,
          "reason": "The point can be communicated respectfully through the owner's knowledge and the team's recommendation without implying she lacked market understanding."
        },
        "source_support": {
          "value": 4,
          "reason": "The exchange supports the reported experience and proposed recommendation; it does not establish implementation or results."
        }
      },
      "nearest_alternative": {
        "candidate_key": "m1-geography-and-buyer-knowledge",
        "central_point": "Diagnose an existing lead campaign by separating its narrow recent-visitor audience from the broader geographic targeting decision.",
        "comparison_reason": "That is a meaningful but separate direction from the same moment. The geography point is stronger for this batch because it centers the owner's market knowledge and a concrete collaborative targeting recommendation; the campaign diagnosis would require its own careful treatment of tracking and apparent results."
      }
    },
    {
      "local_key": "m1-market-research-survey-proposal",
      "rank": 2,
      "disposition": "SELECT",
      "title": "Reviews and buying research answer different questions",
      "central_point": "Reviews can show what clients say about their experience, while questions about why they chose a wedding business can provide a different kind of insight for shaping advertising messages.",
      "why_worthwhile": "Whitney describes asking new clients for market research and says clients respond with reviews instead. She distinguishes those inputs and connects buyer triggers to ad copy and landing pages. This offers a useful, specific perspective for owners who have testimonials but want to understand what influenced a couple's decision.",
      "audience": "Wedding business owners who have reviews or testimonials but want clearer insight into why couples chose them.",
      "intended_shift": "Recognize that reviews and decision-focused research can serve different purposes, and consider what additional questions could inform marketing messages.",
      "primary_pillar": "ATTRACT",
      "content_type": "thought_shift",
      "strategic_rationale": "The distinction creates a useful point of view for owners unfamiliar with WIA: it explains why advertising strategy may benefit from learning about buyer decisions, not only collecting praise. Keep Whitney's observation about client responses in its stated context rather than presenting it as an industry-wide pattern.",
      "source_demonstration": "Whitney says that when WIA asks new Elevate clients whether they have market research or data to share, they often offer reviews. She says knowing buyer types and triggers could inform ad copy and landing pages.",
      "moment_keys": [
        "m1-market-research-survey-proposal"
      ],
      "evidence_refs": [
        "m1.t0548",
        "m1.t0553",
        "m1.t0558",
        "m1.t0565",
        "m1.t0577"
      ],
      "claims": [
        {
          "claim": "Whitney says WIA asks new Elevate clients about market research and that clients offer reviews in response.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0548",
            "m1.t0553"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Whitney distinguishes reviews from market research and says understanding buyer types and triggers could inform ad copy and landing pages.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0558",
            "m1.t0565",
            "m1.t0577"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Reviews and decision-focused research can answer different marketing questions.",
          "state": "editorial_inference",
          "source_refs": [
            "m1.t0553",
            "m1.t0558",
            "m1.t0565"
          ],
          "knowledge_refs": []
        }
      ],
      "claim_boundaries": [
        "Do not generalize Whitney's account of WIA onboarding conversations into a claim about all wedding professionals.",
        "Do not imply reviews have no value; the point is that reviews and decision-focused research can serve different purposes.",
        "The exchange supports a proposed use for research, not a demonstrated improvement in ads, landing pages, or business outcomes."
      ],
      "development_direction": "Contrast the questions each input can answer: a review offers a client's account of their experience, while a question about why they chose the business seeks decision context. Use Whitney's onboarding example and her proposed connection to ad copy and landing pages without claiming the proposed survey workflow was launched.",
      "tension": "A business may have reviews to share while still lacking the decision context it wants for marketing.",
      "offer_connection": null,
      "possible_format": "A concise educational perspective.",
      "judgments": {
        "audience_relevance": {
          "value": 4,
          "reason": "Owners with testimonials can recognize the distinction between praise and information about what influenced a booking decision."
        },
        "strategic_value_brand_fit": {
          "value": 4,
          "reason": "The point connects buyer understanding to advertising messages, consistent with WIA's strategic perspective."
        },
        "distinctiveness": {
          "value": 4,
          "reason": "It makes a specific distinction between reviews and decision-focused research rather than repeating a broad claim that research matters."
        },
        "appropriate_depth": {
          "value": 4,
          "reason": "The exchange gives a clear distinction and a marketing application, while a public treatment should avoid adding an unshown research method."
        },
        "voice_framing": {
          "value": 4,
          "reason": "The point respects the value of reviews and invites a useful additional question without criticizing owners."
        },
        "source_support": {
          "value": 4,
          "reason": "Whitney states the distinction and its proposed application; no research workflow or resulting performance is demonstrated."
        }
      },
      "nearest_alternative": {
        "candidate_key": "m1-market-research-survey-proposal",
        "central_point": "WIA is developing a LeadLock survey and spreadsheet workflow as a potential client-value differentiator.",
        "comparison_reason": "That alternative is not suitable as a public offer or process claim from this exchange: the workflow is proposed, and the differentiator claim is not supported by competitor research. The selected point uses the supported distinction and buyer-message connection without implying implementation."
      }
    }
  ],
